void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    vec3 prev = texture(iChannel0, uv).rgb;
    vec3 add = vec3(uv.x, uv.y, 0.5);
    fragColor = vec4(prev * 0.9 + add * 0.1, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    vec3 trail = texture(iChannel0, uv).rgb;
    fragColor = vec4(trail, 1.0);
}
